const listExpenses = `-- name: ListExpenses :many
select e.id, e.expense_date, e.received_at, e.status, ec.name as category, ec.financial_group,
       s.name as supplier, e.amount, e.currency, e.description, e.doc_kind, e.doc_folio,
       e.paid_at, ub.name as created_by_name,
       (select string_agg(distinct pm.name, ' + ' order by pm.name)
          from expense_payments ep join payment_methods pm on pm.id = ep.payment_method_id
         where ep.expense_id = e.id) as payment_method,
       (select count(*) from expense_items ei where ei.expense_id = e.id and not ei.excluded) as item_count
from expenses e
join expense_categories ec on ec.id = e.category_id
left join suppliers s on s.id = e.supplier_id
left join users ub on ub.id = e.created_by
where ($1::expense_status is null or e.status = $1)
  and ($2::boolean is not true or (
        e.received_at is null and e.status <> 'cancelada'
        and exists (select 1 from expense_items pi where pi.expense_id = e.id
                     and pi.item_type is not null and pi.voided_at is null and not pi.excluded)))
order by
  case when $3::text = 'amount'      and $4::text = 'asc'  then e.amount end asc  nulls last,
  case when $3::text = 'amount'      and $4::text <> 'asc' then e.amount end desc nulls last,
  case when $3::text = 'status'      and $4::text = 'asc'  then e.status::text end asc  nulls last,
  case when $3::text = 'status'      and $4::text <> 'asc' then e.status::text end desc nulls last,
  case when $3::text = 'category'    and $4::text = 'asc'  then ec.name end asc  nulls last,
  case when $3::text = 'category'    and $4::text <> 'asc' then ec.name end desc nulls last,
  case when $3::text = 'supplier'    and $4::text = 'asc'  then s.name end asc  nulls last,
  case when $3::text = 'supplier'    and $4::text <> 'asc' then s.name end desc nulls last,
  case when $3::text = 'description' and $4::text = 'asc'  then e.description end asc  nulls last,
  case when $3::text = 'description' and $4::text <> 'asc' then e.description end desc nulls last,
  case when $3::text = 'date'        and $4::text = 'asc'  then e.expense_date end asc,
  e.expense_date desc, e.id desc
limit $6 offset $5
`

type ListExpensesParams struct {
	Status         *ExpenseStatus `json:"status"`
	PendingReceipt *bool          `json:"pending_receipt"`
	Sort           string         `json:"sort"`
	Dir            string         `json:"dir"`
	Off            int32          `json:"off"`
	Lim            int32          `json:"lim"`
}

type ListExpensesRow struct {
	ID             int64              `json:"id"`
	ExpenseDate    pgtype.Date        `json:"expense_date"`
	ReceivedAt     pgtype.Date        `json:"received_at"`
	Status         ExpenseStatus      `json:"status"`
	Category       string             `json:"category"`
	FinancialGroup FinancialGroup     `json:"financial_group"`
	Supplier       *string            `json:"supplier"`
	Amount         decimal.Decimal    `json:"amount"`
	Currency       string             `json:"currency"`
	Description    *string            `json:"description"`
	DocKind        *string            `json:"doc_kind"`
	DocFolio       *string            `json:"doc_folio"`
	PaidAt         pgtype.Timestamptz `json:"paid_at"`
	CreatedByName  *string            `json:"created_by_name"`
	PaymentMethod  []byte             `json:"payment_method"`
	ItemCount      int64              `json:"item_count"`
}

// payment_method se agrega desde expense_payments: un gasto puede tener varios medios
// ("Tarjeta + Efectivo"), así que ya no es una columna del encabezado.
// Orden por columna: @sort ∈ (”|date|status|category|supplier|description|amount) × @dir
// (asc|desc); default fecha desc. Va en SQL y no en el cliente porque la lista está paginada:
// ordenar solo las 20 filas visibles daría un orden falso.
func (q *Queries) ListExpenses(ctx context.Context, arg ListExpensesParams) ([]ListExpensesRow, error) {
	rows, err := q.db.Query(ctx, listExpenses,
		arg.Status,
		arg.PendingReceipt,
		arg.Sort,
		arg.Dir,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListExpensesRow{}
	for rows.Next() {
		var i ListExpensesRow
		if err := rows.Scan(
			&i.ID,
			&i.ExpenseDate,
			&i.ReceivedAt,
			&i.Status,
			&i.Category,
			&i.FinancialGroup,
			&i.Supplier,
			&i.Amount,
			&i.Currency,
			&i.Description,
			&i.DocKind,
			&i.DocFolio,
			&i.PaidAt,
			&i.CreatedByName,
			&i.PaymentMethod,
			&i.ItemCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

